const items = $input.all();
const todayStr = DateTime.now().setZone('Africa/Cairo').toFormat('yyyy-LL-dd');
const dateRe = /^\d{4}-\d{2}-\d{2}$/;
const timeRe = /\d{1,2}:\d{2}/;

const todayTasks = [];
const trackSummary = {};

for (const item of items) {
  const row = item.json;

  const taskDate = String(row['التاريخ'] ?? '').trim();
  const time = String(row['الوقت'] ?? '').trim();
  // A real routine row has a date AND a time range (e.g. "09:00–12:00").
  // This skips the Daily Summary / Track Summary sections below the table,
  // whose rows carry dates or track names but numeric values elsewhere.
  if (!dateRe.test(taskDate) || !timeRe.test(time)) continue;

  const status = String(row['الحالة'] ?? '').trim().toUpperCase();
  const track = String(row['المسار'] ?? '').trim();
  const done = status === 'TRUE';

  // 1. Collect ALL of today's tasks (done and not done)
  if (taskDate === todayStr) {
    todayTasks.push({
      time: time,
      track: track,
      details: String(row['التفاصيل'] ?? ''),
      link: String(row['الرابط'] ?? ''),
      done: done,
    });
  }

  // 2. Aggregate track statistics for the chart
  if (track && track !== 'راحة') {
    const planned = parseFloat(row['الساعات المخططة'] ?? 0) || 0;
    const doneHours = parseFloat(row['الساعات المنجزة'] ?? 0) || 0;
    if (!trackSummary[track]) trackSummary[track] = { planned: 0, done: 0 };
    trackSummary[track].planned += planned;
    trackSummary[track].done += doneHours;
  }
}

const labels = Object.keys(trackSummary);
const doneData = labels.map((k) => Math.round(trackSummary[k].done * 100) / 100);
const plannedData = labels.map((k) => Math.round(trackSummary[k].planned * 100) / 100);

// Build an embeddable QuickChart image URL (renders as a normal <img> in email)
const chartConfig = {
  type: 'bar',
  data: {
    labels: labels,
    datasets: [
      { label: 'المنجزة', data: doneData, backgroundColor: '#1a73e8' },
      { label: 'المخططة', data: plannedData, backgroundColor: '#c2d7f7' },
    ],
  },
};
const chartUrl = 'https://quickchart.io/chart?w=600&h=350&c=' + encodeURIComponent(JSON.stringify(chartConfig));

// Build the tasks section
let tasksHtml = '';
if (todayTasks.length) {
  for (const t of todayTasks) {
    const linkHtml = t.link
      ? '<a href="' + t.link + '" target="_blank">🔗 رابط الدرس/المصدر</a>'
      : '';
    const statusBadge = t.done ? '✅ تمت' : '⏳ متبقية';
    const itemClass = t.done ? 'task-item done' : 'task-item';
    tasksHtml +=
      '<div class="' + itemClass + '"><b>⏱ ' + t.time + ' | ' + t.track + '</b> <span class="badge">' + statusBadge + '</span><br>📌 ' +
      t.details + '<br>' + linkHtml + '</div>';
  }
} else {
  tasksHtml = '<p>📭 لا توجد مهام مجدولة لليوم.</p>';
}

const emailHtml =
  '<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="UTF-8"><style>' +
  'body { font-family: Arial, sans-serif; background-color: #f4f6f9; padding: 20px; }' +
  '.card { background: #ffffff; padding: 20px; border-radius: 10px; max-width: 640px; margin: auto; box-shadow: 0 2px 5px rgba(0,0,0,0.1); }' +
  'h2 { color: #1a73e8; border-bottom: 2px solid #1a73e8; padding-bottom: 8px; }' +
  '.task-item { background: #f8f9fa; padding: 10px; margin-bottom: 8px; border-right: 4px solid #1a73e8; border-radius: 4px; }' +
  '.task-item.done { border-right-color: #34a853; opacity: 0.85; }' +
  '.badge { font-size: 12px; color: #555; }' +
  'a { color: #1a73e8; text-decoration: none; font-weight: bold; }' +
  'img { max-width: 100%; height: auto; }' +
  '</style></head><body><div class="card">' +
  '<h2>📋 جدول مهام اليوم (' + todayStr + ')</h2>' +
  tasksHtml +
  '<h2>📊 نسبة التقدم والتوزيع الإجمالي</h2>' +
  '<p>تجدين أدناه المخطط البياني المحدث لتقدمك في جميع المسارات:</p>' +
  '<img src="' + chartUrl + '" alt="Progress chart" />' +
  '</div></body></html>';

return [{
  json: {
    today_str: todayStr,
    today_tasks: todayTasks,
    chart_labels: labels,
    chart_done: doneData,
    chart_planned: plannedData,
    chart_url: chartUrl,
    emailHtml: emailHtml,
  },
}];
